\newcommand{\Comm}{\mathsf{Comm}}

\title{Universal Mathematics and Alien Arithmetic: A Semantic Theory of the
Truths Every Consistent Reasoner Must Accept}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\begin{abstract}
Would a non-human intelligence---extraterrestrial, artificial, or independently
evolved---discover the same mathematics we did? We give one precise reading of
this question and answer it. Working in a purely semantic framework of
structures, sentences, theories, and entailment, we define a sentence to be
\emph{universal over a base theory} when it is entailed by every consistent
extension of that theory. Our central metatheorem, the Universality Theorem,
shows that over a consistent base theory universality coincides exactly with
ordinary provability. As corollaries we obtain a monotonicity principle (basic
arithmetic is inherited by every consistent extension), an ``Independence Defeats
Universality'' theorem (the abstract non-universality of the parallel postulate,
instantiated by the independence of commutativity from the group axioms), and a
Decidability Reduction recasting ``the Riemann Hypothesis is universal'' as the
open problem ``arithmetic decides the Riemann Hypothesis.'' Descending to
concrete number theory, we prove that the prime numbers are a definitional
invariant of multiplicative structure: three independent characterizations
isolate the identical primes, a canonical prime-finding procedure always
succeeds, and Euclid's theorem and the Fundamental Theorem of Arithmetic hold.
The style of a mathematics is contingent; its arithmetic core is forced.
\end{abstract}

\maketitle

\section{Introduction}
The question ``would aliens do the same mathematics?'' is usually treated as
philosophy. Our aim is to convert one sharp version of it into mathematics and
settle that version rigorously. The intuition to formalize is: a truth is
\emph{universal} if any sufficiently expressive, self-consistent reasoner is
forced to accept it. A reasoner starts from base commitments (axioms) and may
strengthen them arbitrarily, subject only to remaining consistent; a universal
truth is one no such strengthening can escape.

We adopt a semantic viewpoint: theories are sets of sentences, sentences are
properties of structures, and the fundamental relation is entailment (truth in
all models). Our contributions are: a minimal framework for universality over a
base theory (\S3); the Universality Theorem (\S4); Independence Defeats
Universality with a group-theoretic instantiation (\S5); the Decidability
Reduction locating the RH conjecture (\S6); and a theory of alien arithmetic
establishing primes as a definitional invariant (\S7).

\section{Scope}
The framework is deliberately semantic. It does not contain a syntactic
derivability relation, and so does not by itself invoke G\"odel's incompleteness
theorems; it provides the semantic scaffolding on which such phenomena can later
be expressed. The point is not to reprove classical metatheorems but to isolate
the single notion---universality as entailment by all consistent
extensions---that makes the alien-mathematics question precise.

\section{The framework}
Fix a type $M$ of \emph{structures} or \emph{worlds}.

\begin{definition}[Sentence]
A \emph{sentence} over $M$ is a predicate $\varphi : M \to \{\mathrm{true},
\mathrm{false}\}$. Its \emph{negation} satisfies $(\neg\varphi)(m) \iff
\neg(\varphi(m))$.
\end{definition}
\begin{definition}[Theory]
A \emph{theory} $T$ is a set of sentences over $M$.
\end{definition}
\begin{definition}[Model]
A world $m$ is a \emph{model} of $T$, written $m \models T$, when
$\varphi(m)$ holds for all $\varphi \in T$.
\end{definition}
\begin{definition}[Consistency]
$T$ is \emph{consistent} when $\exists m,\ m \models T$.
\end{definition}
\begin{definition}[Entailment]
$T$ \emph{entails} $\varphi$, written $T \models \varphi$, when $\varphi(m)$
holds for every $m$ with $m \models T$.
\end{definition}
\begin{definition}[Universality]
$\varphi$ is \emph{universal over $T$} when every consistent extension of $T$
entails it: for all $T' \supseteq T$, if $T'$ is consistent then
$T' \models \varphi$.
\end{definition}
\begin{definition}[Decidability]
$T$ \emph{decides} $\varphi$ when $T \models \varphi$ or $T \models \neg\varphi$.
\end{definition}

\section{Basic consequence and the Universality Theorem}
\begin{lemma}[Axioms are entailed]
If $\varphi \in T$ then $T \models \varphi$.
\end{lemma}
\begin{proof}
If $m \models T$ then $m$ satisfies every axiom of $T$, in particular $\varphi$.
\end{proof}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $T \subseteq T'$ and $T \models \varphi$, then $T' \models \varphi$.
\end{lemma}
\begin{proof}
If $m \models T'$ then, as $T \subseteq T'$, $m \models T$, whence $\varphi(m)$.
\end{proof}

Monotonicity is the exact content of ``a foundational theory's theorems are a
subset of the theorems of every consistent extension.''

\begin{lemma}[Consistency forbids contradiction]\label{lem:noncontra}
If $T$ is consistent, then not both $T \models \varphi$ and
$T \models \neg\varphi$.
\end{lemma}
\begin{proof}
A model $m \models T$ would satisfy $\varphi(m)$ and $\neg\varphi(m)$.
\end{proof}

\begin{theorem}[Universality Theorem]\label{thm:univ}
Let $T$ be consistent. Then $\varphi$ is universal over $T$ if and only if
$T \models \varphi$.
\end{theorem}
\begin{proof}
($\Rightarrow$) Apply universality to $T' = T$, using $T \subseteq T$ and the
consistency of $T$. ($\Leftarrow$) For any consistent $T' \supseteq T$,
Lemma~\ref{lem:mono} gives $T' \models \varphi$.
\end{proof}

\begin{corollary}[Axioms are universal]
If $\varphi \in T$ then $\varphi$ is universal over $T$.
\end{corollary}

\begin{corollary}\label{cor:univ-entail}
If $T$ is consistent and $\varphi$ is universal over $T$, then
$T \models \varphi$.
\end{corollary}

\begin{proposition}[Closure]
The sentences universal over $T$ are closed under conjunction and modus ponens.
\end{proposition}
\begin{proof}
Evaluate in an arbitrary consistent extension $T'$ and model $m \models T'$;
conjunction holds pointwise and modus ponens is pointwise implication.
\end{proof}

\section{Independence and the parallel postulate}
\begin{definition}[Independence]
$\varphi$ is \emph{independent over $T$} when $T$ has a model in which $\varphi$
holds and a model in which $\varphi$ fails.
\end{definition}

\begin{lemma}[Countermodels block entailment]
If some model of $T$ falsifies $\varphi$, then $T \not\models \varphi$.
\end{lemma}

\begin{theorem}[Independence Defeats Universality]\label{thm:indep}
If $\varphi$ is independent over $T$, then neither $\varphi$ nor $\neg\varphi$ is
universal over $T$.
\end{theorem}
\begin{proof}
Let $m_1 \models T$ with $\varphi(m_1)$ and $m_2 \models T$ with
$\neg\varphi(m_2)$. Then $T \cup \{\neg\varphi\}$ is consistent (via $m_2$) and
does not entail $\varphi$, so $\varphi$ is not universal. Symmetrically,
$T \cup \{\varphi\}$ is consistent (via $m_1$) and does not entail $\neg\varphi$.
\end{proof}

\begin{corollary}
Over a consistent $T$, not both $\varphi$ and $\neg\varphi$ are universal.
\end{corollary}
\begin{proof}
By Corollary~\ref{cor:univ-entail} both would be entailed, contradicting
Lemma~\ref{lem:noncontra}.
\end{proof}

\subsection{Commutativity as the algebraic parallel postulate}
Consider two worlds: $\mathbb{Z}/2\mathbb{Z}$ (commutative) and the symmetric
group $S_3$ (non-commutative). Let the theory of groups impose no extra axioms,
and let $\Comm$ be the sentence $\forall x,y,\ x\cdot y = y\cdot x$.

\begin{proposition}
$\mathbb{Z}/2\mathbb{Z} \models \Comm$ and $S_3 \not\models \Comm$.
\end{proposition}

\begin{theorem}[Commutativity is not universal]
Over the theory of groups, neither $\Comm$ nor $\neg\Comm$ is universal.
\end{theorem}
\begin{proof}
$\Comm$ is independent over the theory of groups; apply Theorem~\ref{thm:indep}.
\end{proof}

\begin{theorem}[Commutativity becomes universal once adopted]
Over the theory of abelian groups (groups together with $\Comm$), $\Comm$ is
universal.
\end{theorem}
\begin{proof}
$\Comm$ is now an axiom, hence universal; consistency is witnessed by
$\mathbb{Z}/2\mathbb{Z}$.
\end{proof}

\section{The Riemann Hypothesis and the Decidability Reduction}
\begin{theorem}[Decidability Reduction]\label{thm:dec}
Let $T$ be consistent. Then $\varphi$ or $\neg\varphi$ is universal over $T$ if
and only if $T$ decides $\varphi$.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:univ} to $\varphi$ and to $\neg\varphi$ and disjoin the
resulting equivalences.
\end{proof}

Reading $T$ as arithmetic and $\varphi$ as the Riemann Hypothesis,
Theorem~\ref{thm:dec} says ``RH (or its negation) is universal'' if and only if
``arithmetic decides RH.'' The right-hand side is open; hence RH universality is
a genuine conjecture, neither trivially true nor false.

\section{Alien arithmetic: would aliens discover primes?}
A natural number $p$ is \emph{prime} when $p \ge 2$ and its only positive
divisors are $1$ and $p$. We show this notion is robust under three independent
routes.

\begin{theorem}[Primes from the divisibility order]
$p$ is prime iff $p \ge 2$ and $\forall d\ (d \mid p \to d = 1 \vee d = p)$.
\end{theorem}

\begin{theorem}[Primes as indecomposable numbers]
For $p \ge 2$: $p$ is prime iff there do not exist $a,b \ge 2$ with $p = a\cdot
b$.
\end{theorem}
\begin{proof}
If $p$ prime and $p = ab$ with $a,b \ge 2$, then $a \mid p$ forces $a = 1$ or
$a = p$, both contradictory. Conversely a nontrivial divisor $d$ with $p = dc$
yields, after excluding $d \in \{1,p\}$, a factorization with $d,c \ge 2$.
\end{proof}

\begin{theorem}[Primes as abstract atoms]
$p$ is prime iff $p$ is a prime element (dividing a product forces dividing a
factor) and $p$ is irreducible (a non-unit with no nontrivial factorization).
These notions are defined in any commutative monoid.
\end{theorem}

\begin{theorem}[Canonical prime finder]
For every $n \ge 2$, the least divisor of $n$ exceeding $1$ is prime and divides
$n$.
\end{theorem}
\begin{proof}
A nontrivial divisor of that least divisor would be a smaller divisor exceeding
$1$, contradicting minimality.
\end{proof}

\begin{theorem}[Euclid]
For every $n$ there is a prime $p \ge n$; the set of primes is infinite.
\end{theorem}
\begin{proof}
Any prime factor of $n! + 1$ exceeds $n$.
\end{proof}

\begin{theorem}[Fundamental Theorem of Arithmetic]
Every positive natural number is a product of primes; and any two prime-factor
lists of the same number are permutations of one another.
\end{theorem}
\begin{proof}
Existence by strong induction, splitting composites via the prime finder.
Uniqueness from the prime-element property, matching factors across two
factorizations.
\end{proof}

The uniqueness clause is decisive: the prime factorization of a number is a fact
about the number, not a description imposed on it. Two civilizations that never
met agree, factor for factor.

\section{Discussion}
The results split along the contingent/necessary divide. Over a fixed consistent
base, the universal sentences are exactly the theorems
(Theorem~\ref{thm:univ}); primes and unique factorization are forced on any
multiplicative intelligence. Independent sentences---commutativity, the parallel
postulate---are non-universal (Theorem~\ref{thm:indep}) and become universal only
relative to a base adopting them. Whether deep arithmetic statements such as RH
are universal equals whether arithmetic decides them
(Theorem~\ref{thm:dec})---an honest open problem.

\section{Future directions}
(1) Add a syntactic derivability relation $\vdash$ and prove soundness and
completeness. (2) Connect to a formalization of the first incompleteness theorem
to exhibit sentences decided in no recursively axiomatized consistent extension
of arithmetic. (3) Replace the group analogue with a genuine
incidence/betweenness model of the parallel postulate.

\section{Conclusion}
Universality, defined as entailment by every consistent extension, coincides with
provability over any consistent base. This organizes the alien-mathematics
question: foundational arithmetic is provably universal, independent axioms are
provably non-universal, and RH universality reduces to RH decidability. The
primes are a definitional invariant of multiplication, recoverable by three
independent routes and a canonical construction, with Euclid's theorem and unique
factorization intact. Any consistent counting intelligence meets us at the
primes.

\end{document}

