from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def prime_via_divisibility(p: int) -> bool:
    """p >= 2 whose only divisors are 1 and p (the divisibility-order route)."""
    return p >= 2 and all(d == 1 or d == p for d in divisors(p))

def prime_via_indecomposable(p: int) -> bool:
    """p >= 2 not expressible as a*b with a, b >= 2 (the break-apart route)."""
    if p < 2:
        return False
    return not any(a * b == p for a in range(2, p) for b in range(2, p))

def prime_element(p: int, bound: int = 64) -> bool:
    """Abstract prime element: p | a*b  =>  p | a or p | b (the algebraic route)."""
    if p < 2:
        return False
    return all((a * b) % p != 0 or a % p == 0 or b % p == 0
               for a in range(bound) for b in range(bound))

def characterizations_agree(limit: int) -> bool:
    """Verify all three definitions isolate the identical set of primes."""
    d = [p for p in range(2, limit) if prime_via_divisibility(p)]
    i = [p for p in range(2, limit) if prime_via_indecomposable(p)]
    a = [p for p in range(2, limit) if prime_element(p)]
    return d == i == a


if __name__ == '__main__':
    print('characterizations agree up to 200:', characterizations_agree(200))

