DIVISIBILITY(p):     p >= 2 and every divisor d of p is 1 or p
INDECOMPOSABLE(p):   p >= 2 and no a,b >= 2 satisfy a*b = p
PRIME_ELEMENT(p):    p >= 2 and for all a,b: p | a*b  =>  p | a or p | b

AGREE(limit):
    D = { p in [2,limit) : DIVISIBILITY(p) }
    I = { p in [2,limit) : INDECOMPOSABLE(p) }
    A = { p in [2,limit) : PRIME_ELEMENT(p) }
    return D == I == A

