from typing import Callable, Dict, List, Tuple

World = Dict[Tuple[int, int], int]      # a Cayley table over 0..n-1
Sentence = Callable[[World], bool]

def carrier(w: World) -> List[int]:
    return sorted({a for (a, _) in w})

def is_model(theory: List[Sentence], w: World) -> bool:
    return all(phi(w) for phi in theory)

def entails(theory: List[Sentence], phi: Sentence, worlds: List[World]) -> bool:
    """T |= phi : phi holds in every model of T (finite semantic check)."""
    return all(phi(w) for w in worlds if is_model(theory, w))

def universal(theory: List[Sentence], phi: Sentence, worlds: List[World]) -> bool:
    """phi universal over T iff every consistent extension of T entails it.

    By the Universality Theorem, over a consistent base this equals T |= phi;
    we check that characterization directly against the finite world class.
    """
    consistent = any(is_model(theory, w) for w in worlds)
    return consistent and entails(theory, phi, worlds)

def decides(theory: List[Sentence], phi: Sentence, worlds: List[World]) -> bool:
    neg: Sentence = lambda w: not phi(w)
    return entails(theory, phi, worlds) or entails(theory, neg, worlds)

