"""Visualization: three independent prime tests painted on the number line.

Shows that the divisibility, indecomposability, and prime-element definitions
mark exactly the same integers as prime, up to N. Saves prime_agreement.png.
"""
import matplotlib.pyplot as plt

def divisors(n):
    return [d for d in range(1, n + 1) if n % d == 0]

def by_div(p):
    return p >= 2 and all(d in (1, p) for d in divisors(p))

def by_indecomp(p):
    return p >= 2 and not any(a * b == p for a in range(2, p) for b in range(2, p))

def by_prime_elt(p, bound=80):
    return p >= 2 and all((a*b) % p or a % p == 0 or b % p == 0
                          for a in range(bound) for b in range(bound))

N = 60
xs = list(range(2, N))
rows = [
    ("divisibility order", [by_div(p) for p in xs]),
    ("indecomposability", [by_indecomp(p) for p in xs]),
    ("prime element",     [by_prime_elt(p) for p in xs]),
]
fig, ax = plt.subplots(figsize=(12, 3))
for i, (label, mask) in enumerate(rows):
    for x, m in zip(xs, mask):
        ax.scatter(x, i, c="crimson" if m else "#dddddd", s=40, marker="s")
ax.set_yticks(range(len(rows)))
ax.set_yticklabels([r[0] for r in rows])
ax.set_xlabel("n")
ax.set_title("Three routes to 'prime' isolate the identical set")
plt.tight_layout()
plt.savefig("prime_agreement.png", dpi=140)
print("wrote prime_agreement.png")
